function loadTypeTemplate(){
    console.log( "enter loadTypeTemplate");
    if( 0 < typeTemplate.length ){
        console.log("typeTemplate had been loaded.")
        homePage = buildHomePage();
    }
    else {
        fs.readFile("./server_html/typeTemplate.html", function (err, data) {
            if (err) {
                console.log("typeTemplate Not Found.");
            }
            else {
                console.log("type template is loaded.");
                typeTemplate = data.toString();
                myHomePage = buildHomePage();
            }
        });
    }
}

function buildOneArticlePage(ID)
{
    console.log( "enter buildOneArticlePage");
    var homePageResult = "";
    var articleData = myHelper.getArticle(ID);
    if( Object.keys(articleData).length == 0 ){
        console.log( "failed to load articles.");
        return "";
    }
    console.log( "data size : " + articleData.length);

    const count = articleData.length;
    var idvalue = HOME_PAGE_BASE_ID;
    for( var i = 0; i<count; ++i){

        /*console.log(  i + " : " + articleData[i][0] + " , "
         + articleData[i][1] + " , " + articleData[i][2] + " , "
         + articleData[i][3] + " , " + articleData[i][4] + " , "
         + articleData[i][5] + " , " + articleData[i][6] +  " , "
         + articleData[i][7]);*/

        var dateTime = articleData[i][2] + "-" + articleData[i][3] + "-" + articleData[i][4];
        var oneResult = popUpArticleTemplate.replace(fillindatetime, dateTime);

        var typeHTMLsection =  getArticleTypes(articleData[i][1], typeTemplate);// getTypes( articleData[i][1]);
        console.log("type HTML : " + typeHTMLsection);
        //var typeHTMLsection = "<a href=\"javascript:anchorScr(2)\" id=\"anch1\" class =\"af-link\">IOS-TAG</a>"
        //var typeHTMLsection = "<a href=\"#\" id=\"anch1\" class =\"af-link\">IOS-TAG</a>"

        //var typeHTMLsection =  getArticleTypes2(articleData[i][1]);

        var monthdate =  myHelper.getMonthShortName(articleData[i][3]) + " " + articleData[i][4];
        oneResult = oneResult.replace(fillinmonthdate, monthdate);
        oneResult = oneResult.replace(fillinyear, articleData[i][2]);
        oneResult = oneResult.replace(fillintitle, articleData[i][5]);
        oneResult = oneResult.replace(fillindetail, articleData[i][6]);
        oneResult = oneResult.replace(fillinid, ++idvalue);
        oneResult = oneResult.replace(fillinarticleid, "article" + idvalue);
        oneResult = oneResult.replace(fillintype, typeHTMLsection);
        var externalLink = "";
        //console.log( articleData[i][7].length + " : external link :  " + articleData[i][7] );
        if( 0 < articleData[i][7].length){
            externalLink = linkTemplate.replace(fillinextlink, articleData[i][7] );
            //console.log( "externalLink : " + externalLink );
        }
        oneResult = oneResult.replace(fillinlink, externalLink);

        var imagehtml = "";
        if( articleData[i][8] ){
            imagehtml = imageTemplate.replace( fillinBase64, articleData[i][8].toString());
        }
        oneResult = oneResult.replace(fillinimage, imagehtml);

        homePageResult += oneResult;
    }
    //console.log( "\r\nHome Screen is : " + homePageResult);
    console.log("exit buildOneArticlePage");
    return homePageResult;
}

function buildHomePage()
{
    console.log( "enter buildHomePage");
    var homePageResult = "";
    var articleData = myHelper.getAllArticles();
    if( Object.keys(articleData).length == 0 ){
        console.log( "failed to load articles.");
        return "";
    }
    console.log( "data size : " + articleData.length);

    const count = articleData.length;
    var idvalue = HOME_PAGE_BASE_ID;
    for( var i = 0; i<count; ++i){

        /*console.log(  i + " : " + articleData[i][0] + " , "
         + articleData[i][1] + " , " + articleData[i][2] + " , "
         + articleData[i][3] + " , " + articleData[i][4] + " , "
         + articleData[i][5] + " , " + articleData[i][6] +  " , "
         + articleData[i][7]);*/

        var dateTime = articleData[i][2] + "-" + articleData[i][3] + "-" + articleData[i][4];
        var oneResult = articleTemplate.replace(fillindatetime, dateTime);

        var typeHTMLsection =  getArticleTypes(articleData[i][1], typeTemplate);// getTypes( articleData[i][1]);

        var monthdate =  myHelper.getMonthShortName(articleData[i][3]) + " " + articleData[i][4];
        oneResult = oneResult.replace(fillinmonthdate, monthdate);
        oneResult = oneResult.replace(fillinyear, articleData[i][2]);
        oneResult = oneResult.replace(fillintitle, articleData[i][5]);
        oneResult = oneResult.replace(fillindetail, articleData[i][6]);
        oneResult = oneResult.replace(fillinid, ++idvalue);
        oneResult = oneResult.replace(fillinarticleid, "article" + idvalue);
        oneResult = oneResult.replace(fillintype, typeHTMLsection);
        var externalLink = "";
        //console.log( articleData[i][7].length + " : external link :  " + articleData[i][7] );
        if( 0 < articleData[i][7].length){
            externalLink = linkTemplate.replace(fillinextlink, articleData[i][7] );
            //console.log( "externalLink : " + externalLink );
        }
        oneResult = oneResult.replace(fillinlink, externalLink);

        var imagehtml = "";
        if( articleData[i][8] ){
            imagehtml = imageTemplate.replace( fillinBase64, articleData[i][8].toString());
        }
        oneResult = oneResult.replace(fillinimage, imagehtml);

        homePageResult += oneResult;
    }
    //console.log( "\r\nHome Screen is : " + homePageResult);
    console.log("exit buildHomePage");
    return homePageResult;
}

function getArticleTypes(typeValue, typeTemplate)
{
    //var iOSTypeValue = myHelper.IOS_TYPE();

    var types = "";
    if ( myHelper.PHOTO_TYPE() & typeValue) {
        if (0 < types.length) {
            types += ","
        }
        var typeHTML = typeTemplate.replace(fillintypereference, TYPE_PHOTO_CLASS);
        typeHTML = typeHTML.replace(fillintypename, TYPE_PHOTO_NAME);
        types += typeHTML;
    }
    if (myHelper.EXPERIENCE_TYPE() & typeValue) {
        if (0 < types.length) {
            types += ","
        }
        var typeHTML = typeTemplate.replace(fillintypereference, TYPE_EXPERIENCE_CLASS);
        typeHTML = typeHTML.replace(fillintypename, TYPE_EXPERIENCE_NAME);
        types += typeHTML;
    }
    if (myHelper.ANDROID_TYPE() & typeValue) {
        if (0 < types.length) {
            types += ","
        }
        //var typeHTML = typeTemplate.replace(fillintypereference, TYPE_ANDROID_URL);
        var typeHTML = typeTemplate.replace(fillintypereference, TYPE_ANDROID_CLASS);
        typeHTML = typeHTML.replace(fillintypename, TYPE_ANDROID_NAME);
        types += typeHTML;
    }
    if (myHelper.IOS_TYPE() & typeValue) {
        if (0 < types.length) {
            types += ","
        }
        var typeHTML = typeTemplate.replace(fillintypereference, TYPE_IOS_CLASS);
        typeHTML = typeHTML.replace(fillintypename, TYPE_IOS_NAME);
        types += typeHTML;
    }
    if (myHelper.DESIGN_TYPE() & typeValue) {
        if (0 < types.length) {
            types += ","
        }
        var typeHTML = typeTemplate.replace(fillintypereference, TYPE_DESIGN_CLASS);
        typeHTML = typeHTML.replace(fillintypename, TYPE_DESIGN_NAME);
        types += typeHTML;
    }
    if (myHelper.LANGUAGE_TYPE() & typeValue) {
        if (0 < types.length) {
            types += ","
        }
        var typeHTML = typeTemplate.replace(fillintypereference, TYPE_LANGUAGE_CLASS);
        typeHTML = typeHTML.replace(fillintypename, TYPE_LANGUAGE_NAME);
        types += typeHTML;
    }
    if (myHelper.TOOLS_TYPE() & typeValue) {
        if (0 < types.length) {
            types += ","
        }
        var typeHTML = typeTemplate.replace(fillintypereference, TYPE_TOOLS_CLASS);
        typeHTML = typeHTML.replace(fillintypename, TYPE_TOOLS_NAME);
        types += typeHTML;
    }
    if (myHelper.ENGINEERING_TYPE() & typeValue) {
        if (0 < types.length) {
            types += ","
        }
        var typeHTML = typeTemplate.replace(fillintypereference, TYPE_ENGINEERING_CLASS);
        typeHTML = typeHTML.replace(fillintypename, TYPE_ENGINEERING_NAME);
        types += typeHTML;
    }
    if (myHelper.NEWS_TYPE() & typeValue) {
        if (0 < types.length) {
            types += ","
        }
        var typeHTML = typeTemplate.replace(fillintypereference, TYPE_NEWS_CLASS);
        typeHTML = typeHTML.replace(fillintypename, TYPE_NEWS_NAME);
        types += typeHTML;
    }
    //console.log( "type : " + types );
    return types;
};

